package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import net.officefloor.hq.app.claim.LateCharge;

/**
 * A sheet's dated settings: for each key (floor, late-pct, terms, terms-&lt;grade&gt;, clerk-limit, cap, proof-threshold) the values
 * recorded, by from-date (a value null: blank). The value in force on a date is the one with the latest from-date on or
 * before it; before every from-date it is the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none
 * for the clerk limit, the cap, the proof threshold and a grade's own terms).
 */
public record DatedSettings(Map<String, NavigableMap<LocalDate, String>> values) {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The key of a grade's own terms. */
    public static String gradeTerms(String grade) {
        return TERMS + "-" + grade;
    }

    /** The audit field for a from-date typed with a save, " from=<date>", or "" when none was typed (the sheet's today). */
    public static String auditFrom(LocalDate from) {
        return from == null ? "" : " from=" + from;
    }

    /** The date a value saved with this from-date (null: none typed) is recorded from: it, else the sheet's today. */
    public static LocalDate fromOr(LocalDate from, LocalDate today) {
        return from == null ? today : from;
    }

    /** One value recorded from a date. */
    public record FromValue(LocalDate from, String value) {
    }

    /** The value of the key in force on the date (null: blank, or nothing recorded on or before it). */
    private String on(String key, LocalDate date) {
        NavigableMap<LocalDate, String> recorded = values.get(key);
        if (recorded == null || date == null) {
            return null;
        }
        Map.Entry<LocalDate, String> entry = recorded.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    /** The floor in force on the date. */
    public BigDecimal floorOn(LocalDate date) {
        String value = on(FLOOR, date);
        return value == null ? SettingRepository.DEFAULT_FLOOR : new BigDecimal(value).setScale(2);
    }

    /** The late percent in force on the date. */
    public BigDecimal latePctOn(LocalDate date) {
        String value = on(LATE_PCT, date);
        return value == null ? SettingRepository.DEFAULT_LATE_PCT : new BigDecimal(value).setScale(2);
    }

    /** What an overdue claim is charged on the given today: the late percent in force on each 30-day boundary. */
    public LateCharge lateCharge(LocalDate today) {
        return new LateCharge(this::latePctOn, today);
    }

    /** The sheet's terms in days in force on the date. */
    public int termsOn(LocalDate date) {
        String value = on(TERMS, date);
        return value == null ? SettingRepository.DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms in force on the date (null: none, the sheet's terms). */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = on(gradeTerms(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The terms in days for a claim of the grade dated on the date: the grade's own in force then, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The grades' own terms in force on the date, by grade (a grade with none left out). */
    public Map<String, Integer> gradeTermsOn(LocalDate date) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        values.keySet().stream().filter((k) -> k.startsWith(TERMS + "-")).sorted().forEach((key) -> {
            String grade = key.substring(TERMS.length() + 1);
            Integer own = gradeTermsOn(grade, date);
            if (own != null) {
                terms.put(grade, own);
            }
        });
        return terms;
    }

    /** The clerk limit in force on the date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        String value = on(CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The cap in force on the date (null: no cap). */
    public BigDecimal capOn(LocalDate date) {
        String value = on(CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold in force on the date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        String value = on(PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * Whether a claim of the date with this due (null: n/a) needs a proof to be settled or approved: its due is above
     * the proof threshold in force on its date.
     */
    public boolean needsProof(LocalDate date, BigDecimal due) {
        BigDecimal threshold = proofThresholdOn(date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** Every value recorded, by key, oldest from-date first. */
    public Map<String, List<FromValue>> history() {
        Map<String, List<FromValue>> history = new LinkedHashMap<>();
        values.forEach((key, recorded) -> history.put(key,
                recorded.entrySet().stream().map((e) -> new FromValue(e.getKey(), e.getValue())).toList()));
        return history;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.Function;

/**
 * What an overdue claim is charged: for every full 30 days it is overdue (its due-by, fixed when it was created, before
 * the sheet's today), the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of its figure,
 * rounded like the claim's due, the charges added up; a boundary whose percent is 0.00 adds nothing. Never bound by a
 * statement: it follows the sheet's today until the claim is settled. A correction, and a deferred claim, is never charged.
 */
public record LateCharge(Function<LocalDate, BigDecimal> pctOn, LocalDate today) {

    /** The days in each period an overdue claim is charged for. */
    public static final int PERIOD_DAYS = 30;

    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.status().open() || claim.deferred(today) || claim.correction()) {
            return charge;
        }
        long late = ChronoUnit.DAYS.between(claim.dueBy(), today);
        long periods = late > 0 ? late / PERIOD_DAYS : 0;
        for (long period = 1; period <= periods; period++) {
            BigDecimal pct = pctOn.apply(claim.dueBy().plusDays(period * PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(Claim.due(figure, pct, mode));
            }
        }
        return charge;
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * How a claim's live figures (the rate step and the late charge) are rounded: a claim dated before the sheet's
 * policy date rounds half up, one dated on or after it half to even. A correction rounds by the date of the claim it
 * corrects, not its own; {@code dates} holds the claims' dates by number.
 */
public record Rounding(LocalDate policyDate, Map<String, LocalDate> dates) {

    /** The rounding by the policy date for the given claims (those a correction may name). */
    public static Rounding of(LocalDate policyDate, List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim claim : claims) {
            if (claim.number() != null) {
                dates.put(claim.number(), claim.date());
            }
        }
        return new Rounding(policyDate, dates);
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate dateOf(Claim claim) {
        return claim.correction() ? dates.getOrDefault(claim.corrects(), claim.date()) : claim.date();
    }

    /** How the claim's live figures round. */
    public RoundingMode modeFor(Claim claim) {
        return dateOf(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
-- Each statement taken of a person, in order (seq from 1), with its due-total ('n/a' when it had none) and date, so
-- the last one can be cancelled and the person shows the one before it again. A person's last statement before this
-- change is kept as their only known one.
CREATE TABLE person_statement (
    sheet_id VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL,
    seq INT NOT NULL,
    stated_total VARCHAR(30),
    statement_date DATE,
    PRIMARY KEY (sheet_id, person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date)
    SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person WHERE statement_count > 0;
-- A claim's status log: one line per status it has had, oldest first (id order) — the status, the user who
-- gave it, the sheet's today then, and the claim's due as computed at that moment ('n/a' when it had none).
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    status VARCHAR(20) NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    log_date DATE NOT NULL,
    due VARCHAR(30) NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A dated setting's values, each in force from its date until the next one's; before every from-date the
-- sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the clerk limit, the cap and a
-- grade's own terms). setting_value null: blank (no limit, no cap, a grade without its own terms).
CREATE TABLE setting_from (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(20) NOT NULL,
    from_date DATE NOT NULL,
    setting_value VARCHAR(30),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- Values already set carry over as in force from the start.
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '1900-01-01', CAST(due_floor AS VARCHAR(30)) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '1900-01-01', CAST(late_pct AS VARCHAR(30)) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '1900-01-01', CAST(terms AS VARCHAR(30)) FROM sheet WHERE terms <> 14;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '1900-01-01', CAST(clerk_limit AS VARCHAR(30)) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '1900-01-01', CAST(due_cap AS VARCHAR(30)) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '1900-01-01', CAST(terms AS VARCHAR(30)) FROM grade_terms;

